type F = (...args: number[]) => void

function debounce(fn: F, t: number): F {
  let timer: null | ReturnType<typeof setTimeout> = null;
  return function (...args) {
    if (timer) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      fn(...args);
      timer = null;
    }, t);
  }
};

type AnyFunc = (...args: any[]) => any;

function throttle<Func extends AnyFunc = AnyFunc>(fn: Func, t: number): F {
  let last = 0;
  // timer: 保证最后一个被节流的任务被执行, 并且作为是否有被节流的任务在等待被执行的标志
  let timer: null | ReturnType<typeof setTimeout> = null;
  // pending 保存节流期间最新的参数
  let pending: null | Parameters<Func> = null;

  return function (this: ThisParameterType<Func>, ...args: Parameters<Func>) {
    const now = Date.now();
    const elapsed = now - last;

    // last === 0: 首次调用
    // elapsed >= t: 节流期已过
    if (last === 0 || elapsed >= t) {
      last = now;
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      pending = null;
      fn.apply(this, args);
      return;
    }

    // 每次被节流的函数调用, 都需要保存调用参数
    // 但是节流期间, 定时器只需要创建一次
    pending = args;
    if (!timer) { // 不在节流期间
      timer = setTimeout(() => {
        timer = null;
        last = 0; // 允许前缘立即执行
        const args2 = pending;
        pending = null;
        if (args2) {
          fn(...args2); // 尾缘执行
          // 尾缘执行不产生新的节流窗口
        }
      }, Math.max(0, t - elapsed));
    }
  } as F;
}

