function memoize(fn) {
  // arg: 参数数组的元素
  // id: 元素的 id
  let arg2Id = new Map();

  // key: 参数数组的 key
  // ret: 函数的返回值
  let key2ret = new Map();

  // 获取参数数组中某个元素的 ID
  const getId = function (arg) {
    if (arg2Id.has(arg)) {
      return arg2Id.get(arg);
    }
    let id = arg2Id.size;
    arg2Id.set(arg, id);
    return id;
  };

  return function (...args) {
    let key = args.map((item) => getId(item)).join(",");
    if (key2ret.has(key)) {
      return key2ret.get(key);
    }
    let ret = fn(...args);
    key2ret.set(key, ret);
    return ret;
  };
}

