const isObject = (obj) => {
  return typeof obj === 'object' && obj !== null;
}

const isThennable = (obj) => {
  return isObject(obj) && typeof obj.then === 'function';
}

var cancellable = function (generator) {
  let cancel;

  const p = new Promise((resolve, reject) => {

    const run = (arg, doNext = true) => {
      try {
        let val;
        if (doNext) {
          const { value, done } = generator.next(arg);
          if (done) {
            resolve(value);
            return;
          } else {
            val = value;
          }
        } else {
          const { value, done } = generator.throw(arg);
          if (done) {
            resolve(value);
            return;
          } else {
            val = value;
          }
        }
        if (isThennable(val)) {
          val
            .then((res) => run(res), (err) => run(err, false));
        }
      } catch (err) {
        reject(err)
      }
    }
    cancel = () => run("Cancelled", false);
    run(null);
  });

  return [cancel, p];
};

